Min-heap based Dijkstra. In JS use a simple priority queue or the array-based version below.
```js
function dijkstra(graph, src) {
  const dist = new Map();
  for (const n of Object.keys(graph)) dist.set(n, Infinity);
  dist.set(src, 0);
  const pq = [[0, src]];
  while (pq.length) {
    pq.sort((a, b) => a[0] - b[0]);
    const [d, u] = pq.shift();
    if (d > dist.get(u)) continue;
    for (const [v, w] of graph[u] || []) {
      const nd = d + w;
      if (nd < dist.get(v)) { dist.set(v, nd); pq.push([nd, v]); }
    }
  }
  return dist;
}
```
Production: use a real heap for O((V+E) log V).

```js
function topo(V, edges) {
  const g = Array.from({ length: V }, () => []);
  const indeg = new Array(V).fill(0);
  for (const [u, v] of edges) { g[u].push(v); indeg[v]++; }
  const q = [];
  for (let i = 0; i < V; i++) if (indeg[i] === 0) q.push(i);
  const order = [];
  while (q.length) {
    const u = q.shift();
    order.push(u);
    for (const v of g[u]) if (--indeg[v] === 0) q.push(v);
  }
  return order.length === V ? order : null; // null = cycle
}
```

BFS over pattern graph.
```js
function ladderLength(begin, end, list) {
  const set = new Set(list);
  if (!set.has(end)) return 0;
  const q = [[begin, 1]];
  const visited = new Set([begin]);
  while (q.length) {
    const [w, d] = q.shift();
    if (w === end) return d;
    for (let i = 0; i < w.length; i++) {
      for (let c = 97; c <= 122; c++) {
        const nx = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
        if (set.has(nx) && !visited.has(nx)) { visited.add(nx); q.push([nx, d + 1]); }
      }
    }
  }
  return 0;
}
```

```js
class UF {
  constructor(n) { this.p = [...Array(n).keys()]; this.r = new Array(n).fill(0); }
  find(x) { while (this.p[x] !== x) { this.p[x] = this.p[this.p[x]]; x = this.p[x]; } return x; }
  union(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    if (this.r[ra] < this.r[rb]) [ra, rb] = [rb, ra];
    this.p[rb] = ra;
    if (this.r[ra] === this.r[rb]) this.r[ra]++;
    return true;
  }
}
```
With path compression + union by rank: near-O(α(n)).

Patience sorting + binary search.
```js
function lis(nums) {
  const t = [];
  for (const n of nums) {
    let l = 0, r = t.length;
    while (l < r) { const m = (l + r) >> 1; t[m] < n ? l = m + 1 : r = m; }
    t[l] = n;
  }
  return t.length;
}
```

```js
function editDistance(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i-1] === b[j-1]
        ? dp[i-1][j-1]
        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  return dp[m][n];
}
```

```js
function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= amount; i++)
    for (const c of coins)
      if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);
  return dp[amount] === Infinity ? -1 : dp[amount];
}
```

```js
function minWindow(s, t) {
  if (t.length > s.length) return '';
  const need = new Map();
  for (const c of t) need.set(c, (need.get(c) || 0) + 1);
  let have = 0, req = need.size;
  const have_c = new Map();
  let res = [-1, -1], resLen = Infinity;
  let l = 0;
  for (let r = 0; r < s.length; r++) {
    const c = s[r];
    have_c.set(c, (have_c.get(c) || 0) + 1);
    if (need.has(c) && have_c.get(c) === need.get(c)) have++;
    while (have === req) {
      if (r - l + 1 < resLen) { res = [l, r]; resLen = r - l + 1; }
      const lc = s[l];
      have_c.set(lc, have_c.get(lc) - 1);
      if (need.has(lc) && have_c.get(lc) < need.get(lc)) have--;
      l++;
    }
  }
  return resLen === Infinity ? '' : s.slice(res[0], res[1] + 1);
}
```

```js
class Trie {
  constructor() { this.root = {}; }
  insert(w) { let n = this.root; for (const c of w) n = n[c] ??= {}; n.$ = true; }
  find(w) { let n = this.root; for (const c of w) { if (!n[c]) return null; n = n[c]; } return n; }
  search(w) { const n = this.find(w); return !!(n && n.$); }
  startsWith(p) { return !!this.find(p); }
}
```

Detect cycle in directed graph.
```js
function canFinish(n, pre) {
  const g = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [a, b] of pre) { g[b].push(a); indeg[a]++; }
  const q = [];
  for (let i = 0; i < n; i++) if (!indeg[i]) q.push(i);
  let done = 0;
  while (q.length) {
    done++;
    const u = q.shift();
    for (const v of g[u]) if (--indeg[v] === 0) q.push(v);
  }
  return done === n;
}
```

```js
function solveNQueens(n) {
  const res = [];
  const cols = new Set(), d1 = new Set(), d2 = new Set();
  const bt = (r, board) => {
    if (r === n) return res.push(board.map(c => '.'.repeat(c) + 'Q' + '.'.repeat(n - c - 1)));
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || d1.has(r - c) || d2.has(r + c)) continue;
      cols.add(c); d1.add(r - c); d2.add(r + c);
      bt(r + 1, [...board, c]);
      cols.delete(c); d1.delete(r - c); d2.delete(r + c);
    }
  };
  bt(0, []);
  return res;
}
```

```js
function binaryGap(N) {
  const b = N.toString(2);
  let max = 0, cur = -1;
  for (const ch of b) {
    if (ch === '1') { if (cur >= 0) max = Math.max(max, cur); cur = 0; }
    else if (cur >= 0) cur++;
  }
  return max;
}
```

Min-heap of head nodes. Or divide-and-conquer merge pairs.
```js
function mergeKLists(lists) {
  const heap = lists.filter(Boolean).map((n, i) => ({ v: n.val, n }));
  heap.sort((a, b) => a.v - b.v);
  const dummy = { next: null };
  let tail = dummy;
  while (heap.length) {
    const min = heap.shift();
    tail.next = min.n;
    tail = tail.next;
    if (min.n.next) {
      const nxt = { v: min.n.next.val, n: min.n.next };
      let i = 0;
      while (i < heap.length && heap[i].v < nxt.v) i++;
      heap.splice(i, 0, nxt);
    }
  }
  return dummy.next;
}
```

Monotonic deque of indices.
```js
function maxSlidingWindow(nums, k) {
  const dq = [], res = [];
  for (let i = 0; i < nums.length; i++) {
    while (dq.length && nums[dq[dq.length - 1]] < nums[i]) dq.pop();
    dq.push(i);
    if (dq[0] === i - k) dq.shift();
    if (i >= k - 1) res.push(nums[dq[0]]);
  }
  return res;
}
```

Insertion-ordered Map trick (JS Map preserves order).
```js
class LRU {
  constructor(cap) { this.cap = cap; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return -1;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v);
    return v;
  }
  put(k, v) {
    if (this.m.has(k)) this.m.delete(k);
    else if (this.m.size >= this.cap) this.m.delete(this.m.keys().next().value);
    this.m.set(k, v);
  }
}
```
